  color: #fff;
  font-size: 3rem;
  font-weight: 300;
  text-align: right;
  padding: 30px 20px;
  min-height: 100px;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  word-wrap: break-word;
  word-break: break-all;
}

.calculator-keypad {
  display: flex;
  background-color: #000;
}

.input-keys {
  flex: 3;
}

.operator-keys {
  flex: 1;
  background-color: #ff9500;
}

.function-keys {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background-color: #333;
}

