  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-areas:
    "key-1 key-2 key-3"
    "key-4 key-5 key-6"
    "key-7 key-8 key-9"
    "key-0 key-0 key-dot";
  gap: 1px;
  background-color: #333;
}

